#!/usr/bin/env node
// 自動修正の結果を TrainLCD/Issues へ返すコメント本文を組み立てる。
// .github/workflows/auto_fix_from_feedback.yml から呼ばれる前提で、追加依存を
// 持たず Node 24 の標準機能（ESM）だけで完結させている。
//
// エージェントには Issues リポジトリのトークンを渡していないため、判断そのものは
// ワークフローの一時ディレクトリに置かれた verdict.json 経由で受け取る。
// PR が出来ていればそのリンクを、直せないと判断していればその理由を返す。
// どちらでもなければ（実行が途中で落ちた場合など）コメントしない。黙って
// 落ちた実行を「直せませんでした」と報告すると、事実と違う記録が issue に残る。

import { realpathSync } from 'node:fs';
import { appendFile, readFile, writeFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';

// 同じ issue に二度コメントしないための目印。ワークフローは実行前にこの綴りを
// 探し、見つかれば処理そのものを打ち切る。
export const MARKER = '<!-- auto-fix-from-feedback -->';

const FOOTER = '_Generated by [Claude Code](https://claude.ai/code)_';

// 理由はエージェントが書くが、その判断材料は利用者の本文なので untrusted な
// 入力の影響下にある。目印を偽装されるとコメントの重複検知が壊れるため、
// HTML コメントはまとめて落とす。
const HTML_COMMENT_PATTERN = /<!--[\s\S]*?-->/g;
const MAX_REASON_CHARS = 1200;
// 引き継ぎ先は選択肢が決まっているので、想定外の値はそのまま出さない。
const HANDOFF_REPOSITORIES = {
  StationAPI: 'https://github.com/TrainLCD/StationAPI',
  Functions: 'https://github.com/TrainLCD/Functions',
};

export const sanitizeReason = (reason) =>
  String(reason ?? '')
    .replace(HTML_COMMENT_PATTERN, '')
    .replace(/\r\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, MAX_REASON_CHARS);

export const parseVerdict = (raw) => {
  if (typeof raw !== 'string' || raw.trim() === '') {
    return null;
  }
  try {
    const parsed = JSON.parse(raw);
    if (parsed?.outcome !== 'fixed' && parsed?.outcome !== 'declined') {
      return null;
    }
    return {
      outcome: parsed.outcome,
      reason: sanitizeReason(parsed.reason),
      handoff: Object.hasOwn(HANDOFF_REPOSITORIES, parsed.handoff)
        ? parsed.handoff
        : '',
    };
  } catch {
    return null;
  }
};

export const renderLinkComment = (prUrl) =>
  [
    MARKER,
    'フィードバックを起点に自動生成された修正 PR です。',
    '',
    prUrl,
    '',
    '実機での再現確認は行っていません。レビューのうえで採否を判断してください。',
    '',
    '---',
    FOOTER,
    '',
  ].join('\n');

export const renderDeclineComment = ({ reason, handoff }) => {
  const lines = [
    MARKER,
    '自動修正を試みましたが、TrainLCD/MobileApp のコードでは直せないと判断しました。',
    '',
    reason === '' ? '理由は記録されていません。' : reason,
  ];
  if (handoff !== '') {
    lines.push(
      '',
      `対応先: [TrainLCD/${handoff}](${HANDOFF_REPOSITORIES[handoff]})`
    );
  }
  lines.push(
    '',
    'このコメントを消すと、次に条件を満たしたときにもう一度試します。',
    '',
    '---',
    FOOTER,
    ''
  );
  return lines.join('\n');
};

// PR が出来ていればリンクを優先する。エージェントが declined と書いたあとに
// 何らかの理由で PR が残った場合、issue に「直せません」とだけ残るほうが実害が
// 大きいため、実際に出来たものを正とする。
export const decideComment = ({ prUrl, verdict }) => {
  if (typeof prUrl === 'string' && prUrl.trim() !== '') {
    return { action: 'linked', body: renderLinkComment(prUrl.trim()) };
  }
  if (verdict?.outcome === 'declined') {
    return { action: 'declined', body: renderDeclineComment(verdict) };
  }
  return { action: 'none', body: '' };
};

const readOptionalFile = async (path) => {
  if (!path) {
    return '';
  }
  try {
    return await readFile(path, 'utf8');
  } catch (error) {
    if (error?.code === 'ENOENT') {
      return '';
    }
    throw error;
  }
};

const main = async () => {
  const verdict = parseVerdict(await readOptionalFile(process.env.VERDICT_PATH));
  const { action, body } = decideComment({
    prUrl: process.env.PR_URL ?? '',
    verdict,
  });

  if (process.env.GITHUB_OUTPUT) {
    await appendFile(process.env.GITHUB_OUTPUT, `action=${action}\n`, 'utf8');
  }

  if (action === 'none') {
    console.log('::notice::PR も判断結果も残っていないため、issue へのコメントは行いません');
    return;
  }

  const outputPath = process.env.OUTPUT_PATH;
  if (!outputPath) {
    throw new Error('環境変数 OUTPUT_PATH は必須です');
  }
  await writeFile(outputPath, body, 'utf8');
  console.log(`issue へ投稿する内容を書き出しました (${action})`);
};

// テストから純粋関数を import できるよう、直接起動されたときだけ main() を走らせる。
const isDirectRun = () => {
  const entry = process.argv[1];
  if (!entry) {
    return false;
  }
  try {
    return import.meta.url === pathToFileURL(realpathSync(entry)).href;
  } catch {
    return false;
  }
};

if (isDirectRun()) {
  main().catch((error) => {
    console.error(`::error::コメント本文の組み立てに失敗しました: ${error.message}`);
    process.exitCode = 1;
  });
}
